export DEPS_PATH=$SRC/deps
mkdir -p $DEPS_PATH
cd $SRC/x265/build/linux
cmake -G "Unix Makefiles"     -DCMAKE_C_COMPILER=$CC -DCMAKE_CXX_COMPILER=$CXX     -DCMAKE_C_FLAGS="$CFLAGS" -DCMAKE_CXX_FLAGS="$CXXFLAGS"     -DCMAKE_INSTALL_PREFIX="$DEPS_PATH"     -DENABLE_SHARED:bool=off     ../../source
make clean
make -j$(nproc) x265-static
make install
cd $SRC/libde265
./autogen.sh
./configure     --prefix="$DEPS_PATH"     --disable-shared     --enable-static     --disable-dec265     --disable-sherlock265     --disable-hdrcopy     --disable-enc265     --disable-acceleration_speed
make clean
make -j$(nproc)
make install
rm -f $DEPS_PATH/lib/*.so
rm -f $DEPS_PATH/lib/*.so.*
cd $SRC/libheif
./autogen.sh
PKG_CONFIG="pkg-config --static" PKG_CONFIG_PATH="$DEPS_PATH/lib/pkgconfig" ./configure     --disable-shared     --enable-static     --disable-examples     --disable-go     --enable-libfuzzer="$LIB_FUZZING_ENGINE"
make clean
make -j$(nproc)
cp libheif/*-fuzzer $OUT
cp fuzzing/dictionary.txt $OUT/box-fuzzer.dict
